record Node<T>(T head, Node<T> tail) {
    static <T> Node<T> empty() { return null; }
    static <T> Node<T> prepend(T value, Node<T> list) { return new Node<>(value, list); }

    int size() { return 1 + (tail == null ? 0 : tail.size()); }

    boolean contains(T value) {
        if (head.equals(value)) return true;
        return tail != null && tail.contains(value);
    }

    String toList() { return head + (tail == null ? "" : ", " + tail.toList()); }
}

