record Tree(int value, Tree left, Tree right) {
    static Tree leaf(int v) { return new Tree(v, null, null); }

    int size() { return 1 + (left == null ? 0 : left.size()) + (right == null ? 0 : right.size()); }
    int sum() { return value + (left == null ? 0 : left.sum()) + (right == null ? 0 : right.sum()); }

    int height() {
        int lh = left == null ? 0 : left.height();
        int rh = right == null ? 0 : right.height();
        return 1 + Math.max(lh, rh);
    }

    boolean contains(int v) {
        if (value == v) return true;
        if (v < value) return left != null && left.contains(v);
        return right != null && right.contains(v);
    }
}

