record State(String name) {}
record Transition(State from, String event, State to) {}
record Machine(State current, Transition[] transitions) {
    Machine transition(String event) {
        for (Transition t : transitions) {
            if (t.from().equals(current) && t.event().equals(event)) {
                return new Machine(t.to(), transitions);
            }
        }
        return this; // brak przejscia - zostajemy w tym samym stanie
    }
}

State idle = new State("IDLE");
State brewing = new State("BREWING");
State ready = new State("READY");

Transition[] transitions = {
    new Transition(idle, "start", brewing),
    new Transition(brewing, "finish", ready),
    new Transition(ready, "collect", idle)
};

Machine machine = new Machine(idle, transitions);
machine = machine.transition("start");
System.out.println(machine.current());
machine = machine.transition("finish");
System.out.println(machine.current());

