import java.util.Arrays;
import java.util.stream.Stream;

record Book(String isbn, String title, String author, int year) {}
record Borrower(String id, String name) {}
record Loan(Book book, Borrower borrower, long borrowedAt, long dueAt) {}
record Library(Book[] catalog, Loan[] loans) {
    Library addBook(Book book) {
        Book[] newCatalog = Stream.concat(Arrays.stream(catalog), Stream.of(book)).toArray(Book[]::new);
        return new Library(newCatalog, loans);
    }

    Library borrow(Book book, Borrower borrower, long now, long due) {
        Loan[] newLoans = Stream.concat(Arrays.stream(loans), Stream.of(new Loan(book, borrower, now, due))).toArray(Loan[]::new);
        return new Library(catalog, newLoans);
    }

    Library returnBook(Book book) {
        Loan[] remaining = Arrays.stream(loans).filter(l -> !l.book().equals(book)).toArray(Loan[]::new);
        return new Library(catalog, remaining);
    }

    Loan[] overdueLoans(long now) {
        return Arrays.stream(loans).filter(l -> l.dueAt() < now).toArray(Loan[]::new);
    }
}

Library lib = new Library(new Book[0], new Loan[0]);
